import React, { useState } from "react";

function MainMenu() {
    const [hoveredIndex, setHoveredIndex] = useState(null);

    const menuItems = [
        { label: "Calendar", icon: "calendar_today", color: "#4834d4" },
        { label: "Layout", icon: "grid_view", color: "#eb4d4b" },
        { label: "Events", icon: "event", color: "#6ab04c" },
        { label: "Stats", icon: "insights", color: "#f0932b" },
    ];

    const containerStyle = {
        display: "grid",
        gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
        gap: "24px",
        padding: "40px",
        backgroundColor: "#f8f9fa",
        fontFamily: "'Inter', sans-serif",
    };

    return (
        <div style={containerStyle}>
            {menuItems.map((item, index) => {
                const isHovered = hoveredIndex === index;

                return (
                    <div
                        key={item.label}
                        onMouseEnter={() => setHoveredIndex(index)}
                        onMouseLeave={() => setHoveredIndex(null)}
                        style={{
                            padding: "30px 20px",
                            borderRadius: "24px",
                            backgroundColor: "#ffffff",
                            boxShadow: isHovered
                                ? `0 20px 25px -5px ${item.color}20, 0 10px 10px -5px ${item.color}10`
                                : "0 4px 6px -1px rgba(0, 0, 0, 0.1)",
                            display: "flex",
                            flexDirection: "column",
                            alignItems: "center",
                            transition: "all 0.3s cubic-bezier(0.4, 0, 0.2, 1)",
                            transform: isHovered ? "translateY(-8px)" : "translateY(0)",
                            cursor: "pointer",
                            border: "1px solid #f1f2f6"
                        }}
                    >
                        {/* Icon Container */}
                        <div style={{
                            width: 64,
                            height: 64,
                            borderRadius: "20px",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            marginBottom: 20,
                            background: isHovered ? item.color : `${item.color}12`,
                            color: isHovered ? "#fff" : item.color,
                            transition: "all 0.3s ease",
                        }}>
                            <span className="material-icons-round" style={{ fontSize: "28px" }}>
                                {item.icon}
                            </span>
                        </div>

                        {/* Text Content */}
                        <div style={{
                            fontWeight: "700",
                            fontSize: "1.1rem",
                            color: "#2d3436",
                            letterSpacing: "-0.01em"
                        }}>
                            {item.label}
                        </div>

                        <div style={{
                            fontSize: "0.85rem",
                            color: "#636e72",
                            marginTop: 8,
                            opacity: isHovered ? 1 : 0.8
                        }}>
                            {item.label === "Stats" ? "View analytics" : `Manage your ${item.label.toLowerCase()}`}
                        </div>
                    </div>
                );
            })}
        </div>
    );
}

export default MainMenu;
